using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// PACK names/flags after the procedure tree (UNAM BNAM PNAM): 174 of the 179 packages in Starfield.esm hold them by
// index (unsigned), 5 don't (index 25 after 28: PilotDockingPackageIgnoreCombat 07D422, LC043_PursuitShipsIgnoreCombat-
// UntilEscape 0DF18B, AnimTest_Sandbox_Package 1D68B1, DefaultMaster_PilotDockingPackage 208F1E, AnimTest_Patrol_Package
// 214B95). The readers now keep the order they read, and the writer uses it while the record has the same indexes there.
public class PackageProcedureTreeOrderTests
{
    // PilotDockingPackageIgnoreCombat (07D422:Starfield.esm), whole record: ... U24 U26 U27 U28 U25 ...
    private const string Pilot = "";

    private static IEnumerable<IPackageGetter> Read(byte[] bytes) => ReadBoth<IPackageGetter>(bytes,
        f => Package.CreateFromBinary(f), (s, p) => PackageBinaryOverlay.PackageFactory(s, p));

    private static List<sbyte> ProcedureTreeIndexes(byte[] record)
    {
        var content = GameConstants.Starfield.MajorRecord(record).Content;
        var ret = new List<sbyte>();
        bool afterXnam = false;
        for (int p = 0; p + 6 <= content.Length; p += 6 + BitConverter.ToUInt16(content.Slice(p + 4, 2)))
        {
            var sig = System.Text.Encoding.ASCII.GetString(content.Slice(p, 4));
            if (sig == "XNAM") afterXnam = true;
            if (afterXnam && sig == "UNAM") ret.Add((sbyte)content[p + 6]);
        }
        return ret;
    }

    [Fact]
    public void ReadOrder_WrittenBackByteForByte()
    {
        var bytes = Record("PACK", Hex(Pilot));
        foreach (var pack in Read(bytes))
        {
            Write(w => pack.WriteToBinary(w)).ShouldBe(bytes);
        }
    }

    [Fact]
    public void ChangedIndexes_WrittenByIndex()
    {
        var pack = Package.CreateFromBinary(new Mutagen.Bethesda.Plugins.Binary.Streams.MutagenFrame(
            new Mutagen.Bethesda.Plugins.Binary.Streams.MutagenMemoryReadStream(Record("PACK", Hex(Pilot)), Meta())));
        pack.Data[0x30] = new APackageData { Name = "Added" };
        var indexes = ProcedureTreeIndexes(Write(w => pack.WriteToBinary(w)));
        indexes.ShouldBe(indexes.OrderBy(k => (byte)k));
        indexes.ShouldContain((sbyte)0x30);
    }

    [Fact]
    public void ChangedName_KeepsReadOrder()
    {
        var pack = Package.CreateFromBinary(new Mutagen.Bethesda.Plugins.Binary.Streams.MutagenFrame(
            new Mutagen.Bethesda.Plugins.Binary.Streams.MutagenMemoryReadStream(Record("PACK", Hex(Pilot)), Meta())));
        pack.Data[0x25].Name = "Renamed";
        var indexes = ProcedureTreeIndexes(Write(w => pack.WriteToBinary(w)));
        indexes.IndexOf(0x25).ShouldBeGreaterThan(indexes.IndexOf(0x28));
    }
}
